1	/**
2	 * Announces conversation view-state changes made on the backend to every attached window.
3	 *
4	 * Only the canonical conversation id and the new `viewed` value travel: a renderer already holds the
5	 * conversation, so it needs the one field that changed, not a republished conversation or card.
6	 * One instance lives in the bridge dispatch, which every window shares, so a write made in one
7	 * window reaches all of them.
8	 */
9	const CONVERSATION_VIEWED_EVENT = 'conversationViewed';
10	
11	class ConversationViewEvents extends EventTarget {
12	    /** Registers a listener and returns the cleanup that removes it. */
13	    subscribe(listener) {
14	        if (typeof listener !== 'function') throw new Error('Conversation view subscription requires a listener');
15	        const handleViewed = (event) => {
16	            try {
17	                listener(event.detail);
18	            } catch (error) {
19	                console.error('Conversation view listener failed', error);
20	            }
21	        };
22	        this.addEventListener(CONVERSATION_VIEWED_EVENT, handleViewed);
23	
24	        return () => this.removeEventListener(CONVERSATION_VIEWED_EVENT, handleViewed);
25	    }
26	
27	    /** Reports a completed view-state write. A failing listener must not stop the others. */
28	    emit(event) {
29	        this.dispatchEvent(new CustomEvent(CONVERSATION_VIEWED_EVENT, { detail: event }));
30	    }
31	}
32	
33	module.exports = { ConversationViewEvents };
