12	/** Remembers primary-worktree files the desktop wrote without committing, so integration can commit them once. */
13	class UncommittedProjectWrites {
14	    constructor(dependencies = {}) {
15	        this.commitTrackedPaths = dependencies.commitTrackedPaths ?? commitTrackedPaths;
16	        this.pathExists = dependencies.pathExists ?? pathExists;
17	        this.pathsByRoot = new Map();
18	    }
19	
20	    /** Records written files (absolute or root-relative) for the repository root. */
21	    mark(rootPath, filePaths) {
22	        const key = projectKey(rootPath);
23	        const paths = this.pathsByRoot.get(key) ?? new Set();
24	        filePaths.forEach((filePath) => paths.add(relativeRepositoryPath(rootPath, filePath)));
25	        this.pathsByRoot.set(key, paths);
26	    }
27	
28	    /**
29	     * Commits every marked file of the root in one commit and clears them. Files removed since they were written
30	     * are dropped, because Git cannot stage a path that is neither on disk nor in the index.
31	     */
32	    async commit(rootPath) {
33	        const key = projectKey(rootPath);
34	        const paths = [...(this.pathsByRoot.get(key) ?? [])];
35	        if (paths.length === 0) return null;
36	        const existence = await Promise.all(paths.map((relativePath) => this.pathExists(path.join(rootPath, relativePath))));
37	        const existingPaths = paths.filter((_relativePath, index) => existence[index]);
38	        const commit = existingPaths.length > 0
39	            ? await this.commitTrackedPaths(rootPath, existingPaths, COMMIT_MESSAGE)
40	            : null;
41	        const remaining = this.pathsByRoot.get(key);
42	        paths.forEach((relativePath) => remaining?.delete(relativePath));
43	        if (remaining?.size === 0) this.pathsByRoot.delete(key);
44	
45	        return commit;
46	    }
47	}
48	
49	const uncommittedProjectWrites = new UncommittedProjectWrites();
50	
51	module.exports = { UncommittedProjectWrites, uncommittedProjectWrites };
